import json
from fractions import Fraction as F


def main():
    N = 2000  # integer window for n = floor(x); edge effects are excluded by the cutoff C below

    # For x in [n, n+1): g(x) = n^2 - x lies in (n^2 - n - 1, n^2 - n]
    ivs = []
    for n in range(-N, N + 1):
        lo = F(n * n - n - 1)
        hi = F(n * n - n)
        ivs.append((lo, hi))
    ivs.sort()

    # Merge half-open intervals (lo, hi]; touching intervals (a, b] and (b, c] merge
    merged = []
    for lo, hi in ivs:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    # Values <= C are fully determined by n in [-N, N]
    C = F(N * N - N - 2)
    trusted = [(lo, hi) for lo, hi in merged if hi <= C]

    # Check the closed form: pieces are (k(k+1)-1, k(k+1)] for k >= 0
    closed = [(F(k * (k + 1) - 1), F(k * (k + 1))) for k in range(0, 60)]
    formula_ok = all(
        any(lo == a and hi == b for lo, hi in merged) for a, b in closed
    )

    # Exhaustive rational check: every sampled g(x) must land in the merged set,
    # and every merged piece must be hit by some sampled x.
    def g(x):
        return F(x.numerator // x.denominator) ** 2 - x

    def in_set(y, intervals):
        return any(lo < y <= hi for lo, hi in intervals)

    mismatches = 0
    hit = [False] * len(trusted)
    for j in range(-240, 240):
        x = F(j, 12)
        y = g(x)
        if y <= C:
            if not in_set(y, trusted):
                mismatches += 1
            for idx, (lo, hi) in enumerate(trusted):
                if lo < y <= hi:
                    hit[idx] = True

    # Build the answer from computed pieces
    pieces = [f"({float(lo):g}, {float(hi):g}]" if lo.denominator == 1 and hi.denominator == 1
              else f"({lo}, {hi}]" for lo, hi in trusted[:6]]
    final_answer = (
        "Range = " + " ∪ ".join(pieces) +
        " ∪ ... = ⋃_{k≥0} (k(k+1)−1, k(k+1)]  (gaps such as (0,1] and (2,5] are excluded)"
    )

    result = {
        "final_answer": final_answer,
        "evidence": {
            "n_window": N,
            "trusted_piece_count": len(trusted),
            "first_pieces": [[str(lo), str(hi)] for lo, hi in trusted[:6]],
            "closed_form_matches": formula_ok,
            "sample_mismatches": mismatches,
            "all_pieces_hit_by_samples": all(hit),
            "gap_example": ["(0,1]", "excluded"],
        },
    }
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
